def _get_merge_keys(self):
    """
    Note: has side effects (copy/delete key columns)

    Parameters
    ----------
    left
    right
    on

    Returns
    -------
    left_keys, right_keys
    """
    left_keys = []
    right_keys = []
    join_names = []
    right_drop = []
    left_drop = []

    left, right = self.left, self.right

    is_lkey = lambda x: is_array_like(x) and len(x) == len(left)
    is_rkey = lambda x: is_array_like(x) and len(x) == len(right)

    if _any(self.left_on) and _any(self.right_on):
        for lk, rk in zip(self.left_on, self.right_on):
            if is_lkey(lk):
                left_keys.append(left._get_label_or_level_values(lk))
                join_names.append(lk)  # join name reflects the left key
                if is_rkey(rk):
                    right_keys.append(rk)
                else:
                    right_keys.append(right._get_label_or_level_values(rk) if rk is not None else right.index)
            else:
                right_keys.append(right._get_label_or_level_values(rk) if is_rkey(rk) else right.index)
                if lk is not None:
                    left_keys.append(left._get_label_or_level_values(lk))
                    join_names.append(lk)

    elif _any(self.left_on):
        for k in self.left_on:
            if is_lkey(k):
                left_keys.append(k)
                join_names.append(None)
            else:
                left_keys.append(left._get_label_or_level_values(k))
                join_names.append(k)
        if isinstance(self.right.index, MultiIndex):
            right_keys = [
                lev._values.take(lev_codes)
                for lev, lev_codes in zip(
                    self.right.index.levels, self.right.index.codes
                )
            ]
        else:
            right_keys = [self.right.index._values]

    elif _any(self.right_on):
        for k in self.right_on:
            if is_rkey(k):
                right_keys.append(k)
                join_names.append(None)
            else:
                right_keys.append(right._get_label_or_level_values(k))
                join_names.append(k)
        if isinstance(self.left.index, MultiIndex):
            left_keys = [
                lev._values.take(lev_codes)
                for lev, lev_codes in zip(
                    self.left.index.levels, self.left.index.codes
                )
            ]
        else:
            left_keys = [self.left.index.values]

    if left_drop:
        self.left = self.left._drop_labels_or_levels(left_drop)

    if right_drop:
        self.right = self.right._drop_labels_or_levels(right_drop)

    # Ensure the alignment of keys and their types considering timezone awareness.
    left_keys = [pd.Series(key).dt.tz_localize(None) if is_datetime64tz_dtype(key.dtype) else key for key in left_keys]
    right_keys = [pd.Series(key).dt.tz_localize(None) if is_datetime64tz_dtype(key.dtype) else key for key in right_keys]

    return left_keys, right_keys, join_names
