            right_keys = [
                lev._values.take(lev_codes)
                for lev, lev_codes in zip(self.right.index.levels, self.right.index.codes)
            ]
        else:
            right_keys = [self.right.index._values]
    elif _any(self.right_on):
        for k in self.right_on:
            if is_rkey(k):
                right_keys.append(k)
                join_names.append(None)
            else:
                right_keys.append(right._get_label_or_level_values(k))
                join_names.append(k)
        if isinstance(self.left.index, MultiIndex):
            left_keys = [
                lev._values.take(lev_codes)
                for lev, lev_codes in zip(self.left.index.levels, self.left.index.codes)
            ]
        else:
            left_keys = [self.left.index.values]

    if left_drop:
        self.left = self.left._drop_labels_or_levels(left_drop)

    if right_drop:
        self.right = self.right._drop_labels_or_levels(right_drop)

    # Coerce keys to compatible dtypes if necessary
    for i in range(len(left_keys)):
        if not is_dtype_equal(left_keys[i].dtype, right_keys[i].dtype):
            if is_datetime64tz_dtype(left_keys[i].dtype) and is_datetime64tz_dtype(right_keys[i].dtype):
                left_keys[i] = left_keys[i].astype('datetime64[ns, UTC]')
                right_keys[i] = right_keys[i].astype('datetime64[ns, UTC]')

    return left_keys, right_keys, join_names
