```python
def _get_merge_keys(self):
    """
    Note: has side effects (copy/delete key columns)

    Parameters
    ----------
    left
    right

    Returns
    -------
    left_keys, right_keys
    """
    left_keys = []
    right_keys = []
    join_names = []
    right_drop = []
    left_drop = []

    left, right = self.left, self.right

    is_lkey = lambda x: is_array_like(x) and len(x) == len(left)
    is_rkey = lambda x: is_array_like(x) and len(x) == len(right)

    # Check and handle left_on and right_on keys
    if _any(self.left_on) and _any(self.right_on):
        for lk, rk in zip(self.left_on, self.right_on):
            if is_lkey(lk):
                left_keys.append(left._get_label_or_level_values(lk))
                join_names.append(lk if lk is not None else None)
                if is_rkey(rk):
                    right_keys.append(right._get_label_or_level_values(rk))
                else:
                    if rk is not None:
                        right_keys.append(right._get_label_or_level_values(rk))
                        join_names.append(rk)
                    else:
                        # handle case where rk is None
                        right_keys.append(right.index)
                        join_names.append(right.index.name)
            else:
                if not is_rkey(rk):
                    if rk is not None:
                        right_keys.append(right._get_label_or_level_values(rk))
                    else:
                        right_keys.append(right.index)
                    if lk is not None and lk == rk:
                        if len(left) > 0:
                            right_drop.append(rk)
                        else:
                            left_drop.append(lk)
                else:
                    right_keys.append(rk)

                if lk is not None:
                    left_keys.append(left._get_label_or_level_values(lk))
                    join_names.append(lk)
                else:
                    left_keys.append(left.index)
                    join_names.append(left.index.name)
    elif _any(self.left_on):
        for k in self.left_on:
            if is_lkey(k):
                left_keys.append(k)
                join_names.append(None)
            else:
                left_keys.append(left._get_label_or_level_values(k))
                join_names.append(k)

        right_keys = [right.index._values]
    elif _any(self.right_on):
        for k in self.right_on:
            if is_rkey(k):
                right_keys.append(k)
                join_names.append(None)
            else:
                right_keys.append(right._get_label_or_level_values(k))
                join_names.append(k)

        left_keys = [left.index.values]

    # Update left and right based on drop lists
    if left_drop:
        self.left = self.left._drop_labels_or_levels(left_drop)

    if right_drop:
        self.right = self.right._drop_labels_or_levels(right_drop)

    return left_keys, right_keys, join_names
